--
-- Table structure for table `workflow_runs`
--

DROP TABLE IF EXISTS `workflow_runs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `workflow_runs` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `run_id` varchar(64) NOT NULL,
  `user_id` int(11) NOT NULL,
  `workflow_code` varchar(32) NOT NULL,
  `client_request_id` varchar(128) NOT NULL,
  `status` varchar(32) NOT NULL,
  `billing_status` varchar(32) NOT NULL,
  `estimated_count` int(11) NOT NULL DEFAULT '0',
  `actual_completed_count` int(11) DEFAULT NULL,
  `estimated_frozen_points` int(11) NOT NULL DEFAULT '0',
  `final_charge_points` int(11) NOT NULL DEFAULT '0',
  `refund_points` int(11) NOT NULL DEFAULT '0',
  `request_payload_summary` json DEFAULT NULL,
  `result_summary` text,
  `result_summary_url` varchar(500) DEFAULT NULL,
  `result_urls_json` json DEFAULT NULL,
  `external_task_id` varchar(128) DEFAULT NULL,
  `error_message` text,
  `started_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `expires_at` datetime DEFAULT NULL,
  `finished_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `run_id` (`run_id`),
  UNIQUE KEY `uk_workflow_runs_user_workflow_client` (`user_id`,`workflow_code`,`client_request_id`),
  KEY `idx_workflow_runs_user_id` (`user_id`),
  KEY `idx_workflow_runs_workflow_code` (`workflow_code`),
  KEY `idx_workflow_runs_created_at` (`created_at`),
  KEY `idx_workflow_runs_expires_at` (`expires_at`),
  CONSTRAINT `fk_workflow_runs_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=483 DEFAULT CHARSET=utf8mb4;
/*!40101 SET character_set_client = @saved_cs_client */;

